package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class GivenNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property given name of user profile ")
  void test_given_name_v_o_builder() {
    Assertions.assertFalse(GivenNameVO.nullValue().getGivenName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(GivenNameVO.tryFrom(null).getGivenName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", GivenNameVO.from("one").getGivenName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> GivenNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", GivenNameVO.from("one").toString());
  }
}
